foreach(var mf in UnityEngine.Object.FindFirstObjectByType<TownStudy.Builder.BuilderController>().GetComponentsInChildren<UnityEngine.MeshFilter>()){if(mf.name.StartsWith("SourceModule_"))mf.sharedMesh=TownStudy.Builder.RecoveredCatalog.Instance.MeshFor(int.Parse(mf.name.Substring(13)),true);else if(mf.name.StartsWith("SourceDecor_"))mf.sharedMesh=TownStudy.Builder.RecoveredCatalog.Instance.MeshFor(20000+int.Parse(mf.name.Substring(12)),true);}return "Replaced runtime meshes";
